  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 17, $j$5.1 Mental and Emotional Health$j$, $j${"readings": [{"title": "Philippians 4 (King James Version)", "url": "/portal/bible/Philippians/4"}], "body": "Health has parts: physical, mental, emotional, social and spiritual. They are connected, and when one part suffers, the others are affected. Mental and emotional health is how we think, feel and cope with life. Everyone feels stress, sadness, worry and anger at times. These feelings are normal. What matters is how we respond.\n\nStress is the body's reaction to a demand. A little stress can help you perform, but too much for too long can cause headaches, poor sleep, stomach trouble and trouble focusing. Healthy ways to cope include regular physical activity, enough sleep, talking with a trusted person, prayer, reading Scripture, music, time outdoors, good time management and breaking big tasks into small steps. Unhealthy ways include ignoring problems, lashing out, withdrawing from everyone, and using alcohol, drugs or too much screen time to escape.\n\nScripture offers comfort. Philippians 4:6 and 7 says, Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God. And the peace of God, which passeth all understanding, shall keep your hearts and minds through Christ Jesus. First Peter 5:7 says, Casting all your care upon him; for he careth for you.\n\nSometimes sadness, anxiety or hopelessness lasts for weeks or gets in the way of school, sleep, eating or friendships. These are signs that a person needs help from a parent, a school counselor, a pastor, a doctor or a mental health professional. Asking for help is a sign of strength. If you or someone you know is in crisis or thinking about self harm, tell a trusted adult right away. You can call or text 988, the Suicide and Crisis Lifeline, at any time. In an emergency, call 911.\n\nYour task: (1) Define stress and list five healthy ways to cope. (2) Explain when a person should seek help and whom they can ask. (3) Write a personal stress plan using at least three coping skills.\n\nFlorida standards: HE.912.C.1, HE.912.P.7.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "HE.912.C.1, HE.912.P.7", "script": "Welcome back. Listen, we have talked about the body. Today we talk about the mind and the heart.\n\nHealth has parts: physical, mental, emotional, social and spiritual, and they are connected. Mental and emotional health is how we think, feel and cope. Everyone feels stress, sadness, worry and anger at times. Those feelings are normal. What matters is how we respond.\n\nNow watch this. Stress is the body's reaction to a demand. A little can help you perform, but too much for too long can cause headaches, poor sleep and trouble focusing. Healthy ways to cope include physical activity, enough sleep, talking with a trusted person, prayer, Scripture, music, time outdoors and breaking big tasks into small steps. Unhealthy ways include ignoring problems, lashing out, pulling away from everyone, and using drugs, alcohol or too much screen time to escape.\n\nLook at what the Word says. Philippians 4:6 and 7. Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God. And First Peter 5:7. Casting all your care upon him; for he careth for you.\n\nIf sadness or worry lasts for weeks or gets in the way of school, sleep, eating or friends, ask for help from a parent, counselor, pastor or doctor. That is strength, not weakness. If you or someone you know is in crisis, tell a trusted adult right away. You can call or text 988 any time, and in an emergency call 911.\n\nYour task is to define stress, list five coping skills, explain when to seek help and write a stress plan. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.1 Mental and Emotional Health$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 18, $j$5.2 Sleep and Rest$j$, $j${"readings": [{"title": "Psalm 127 (King James Version)", "url": "/portal/bible/Psalms/127"}], "body": "Sleep is not wasted time. During sleep the body repairs muscle, grows, strengthens the immune system and organizes memories. Teens need about 8 to 10 hours of sleep each night, according to the American Academy of Sleep Medicine. Many get far less. Too little sleep can cause poor focus, weak grades, mood swings, a weaker immune system, a greater risk of injury and accidents, and trouble with weight and mood.\n\nTeens often feel sleepy later at night and wake slowly in the morning, but school starts early, so good habits matter. Keep a regular sleep schedule, even on weekends. Put phones, tablets and televisions away at least 30 to 60 minutes before bed, because the light and content can keep the mind awake. Keep your bedroom dark, cool and quiet. Avoid caffeine in the afternoon and evening, including coffee, soda and energy drinks. Finish heavy exercise a few hours before bed, though light activity in the day helps you sleep. Avoid large meals right before bed. A short prayer or a few verses of Scripture before sleep can calm the mind. Naps should be short, about 20 to 30 minutes.\n\nRest is also taught in Scripture. Psalm 127:2 says, It is vain for you to rise up early, to sit up late, to eat the bread of sorrows: for so he giveth his beloved sleep. Psalm 4:8 says, I will both lay me down in peace, and sleep: for thou, LORD, only makest me dwell in safety. God designed a rhythm of work and rest. Rest days also allow the body to recover from training, and over training can cause fatigue, injury and a drop in performance.\n\nYour task: (1) Explain four effects of too little sleep. (2) Write a bedtime routine that supports 8 to 10 hours of sleep. (3) Track your sleep for one week and describe what you learn.\n\nFlorida standards: HE.912.C.1, HE.912.P.7.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "HE.912.C.1, HE.912.P.7", "script": "Welcome back. Listen, some of you are proud of staying up late. Let me tell you why that is not wise.\n\nDuring sleep your body repairs muscle, grows, strengthens your immune system and organizes your memories. Teens need about 8 to 10 hours a night, according to the American Academy of Sleep Medicine. Too little sleep can cause poor focus, weak grades, mood swings, a weaker immune system and a greater risk of injury and accidents.\n\nNow watch this. Here is how to sleep better. Keep a regular schedule, even on weekends. Put phones and screens away 30 to 60 minutes before bed. Keep your room dark, cool and quiet. Avoid caffeine in the afternoon and evening, including soda and energy drinks. Finish hard exercise a few hours before bed. Avoid big meals right before bed. Keep naps to 20 or 30 minutes.\n\nLook at the Word. Psalm 127:2 says, for so he giveth his beloved sleep. And Psalm 4:8, I will both lay me down in peace, and sleep: for thou, LORD, only makest me dwell in safety. God designed a rhythm of work and rest. Rest days also help your body recover from training. Overtraining causes tiredness, injury and poor performance.\n\nYour task is to explain four effects of too little sleep, write a bedtime routine and track your sleep for one week. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.2 Sleep and Rest$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 19, $j$5.3 Avoiding Tobacco, Alcohol and Drugs$j$, $j${"readings": [{"title": "Proverbs 20 (King James Version)", "url": "/portal/bible/Proverbs/20"}], "body": "Substances such as tobacco, vapes, alcohol and drugs can harm a teen's body and brain, damage fitness and ruin goals. The teen brain is still developing until the mid twenties, which makes it more sensitive to damage and addiction. Addiction is a disease in which a person cannot stop using a substance even when it causes harm.\n\nNicotine, found in cigarettes, vapes, cigars and pouches, is highly addictive. Vaping is not harmless water vapor. The aerosol can contain nicotine, chemicals and tiny particles that harm the lungs and heart, and smoking and vaping lower endurance. Federal and Florida law set 21 as the minimum age to buy tobacco and vaping products and alcohol.\n\nAlcohol slows the brain, harms judgment, balance and reaction time, and is linked to accidents, violence and poor decisions. Alcohol use is illegal for those under 21. Proverbs 20:1 says, Wine is a mocker, strong drink is raging: and whosoever is deceived thereby is not wise. Marijuana and other illegal drugs can harm memory, learning, motivation and mental health. Misusing prescription medicines is also dangerous. Counterfeit pills sold on the street or online can contain fentanyl, a powerful drug that can kill with a very small amount. Never take a pill that does not come from a pharmacy and a doctor's prescription for you.\n\nUse refusal skills. Say no clearly. Give a reason, such as I do not want it, or I have practice. Suggest something else. Walk away, and if you are in danger, call a trusted adult for a ride. Choose friends who support you. First Corinthians 6:19 reminds us that the body is the temple of the Holy Ghost. If someone is in danger from a substance, call 911. If you or a friend needs help to stop using, talk to a parent, counselor, pastor or doctor. Help works, and recovery is possible.\n\nYour task: (1) Explain three ways tobacco, vaping and alcohol harm a teen. (2) Describe why counterfeit pills are dangerous. (3) Write a short script using refusal skills for a situation you might face.\n\nFlorida standards: HE.912.C.1, HE.912.B.3, PE.912.R.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "HE.912.C.1, HE.912.B.3, PE.912.R.5", "script": "Welcome back. Listen, this lesson could save a life, maybe yours or a friend's.\n\nSubstances like tobacco, vapes, alcohol and drugs can harm a teen's body and brain, damage fitness and ruin goals. The teen brain is still developing until the mid twenties, so it is more sensitive to damage and addiction. Addiction is a disease in which a person cannot stop using even when it causes harm.\n\nNow watch this. Nicotine, in cigarettes, vapes, cigars and pouches, is highly addictive. Vaping is not harmless water vapor. The aerosol can contain nicotine, chemicals and tiny particles that harm the lungs and heart, and it lowers your endurance. Federal and Florida law set 21 as the minimum age to buy tobacco, vapes and alcohol.\n\nAlcohol slows the brain and harms judgment, balance and reaction time. Proverbs 20:1 says, Wine is a mocker, strong drink is raging: and whosoever is deceived thereby is not wise. Marijuana and other illegal drugs can harm memory, learning and mental health. Counterfeit pills can contain fentanyl, which can kill with a very small amount. Never take a pill that does not come from a pharmacy with a prescription for you.\n\nLook at refusal skills. Say no clearly. Give a reason. Suggest something else. Walk away. Call a trusted adult for a ride. Choose friends who support you. Your body is the temple of the Holy Ghost.\n\nIf someone is in danger, call 911. If you need help to stop, talk to a parent, counselor, pastor or doctor. Help works.\n\nYour task is to explain three harms, explain the danger of counterfeit pills and write a refusal script. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.3 Avoiding Tobacco, Alcohol and Drugs$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 20, $j$5.4 Healthy Relationships and Safety$j$, $j${"readings": [{"title": "Proverbs 1 (King James Version)", "url": "/portal/bible/Proverbs/1"}], "body": "People are made for relationships, and healthy ones help us thrive. A healthy relationship, whether with a friend, family member or someone you date when your family allows it, is marked by respect, honesty, trust, kindness, support and the freedom to say no. An unhealthy relationship may include control, jealousy, name calling, threats, pressure, isolation from other friends or any kind of violence. Abuse is never the fault of the person who is hurt.\n\nPeer pressure is the influence of friends and classmates. It can be good, such as friends who encourage you to study or train, or harmful, such as pressure to break rules or use substances. Proverbs 1:10 says, My son, if sinners entice thee, consent thou not. Know your values, choose friends who share them and practice saying no calmly and firmly.\n\nBullying is repeated, unwanted, hurtful behavior and includes cyberbullying through texts and social media. If you are bullied, tell a trusted adult, save the evidence, and do not retaliate. If you see someone bullied, do not join in, support the person and report it. Treat everyone with respect, because every person is made in God's image.\n\nStay safe online and in public. Do not share passwords, your location or private photos. Never send or forward private pictures of yourself or anyone else, which can be illegal and harmful. If anyone pressures or threatens you, stop, save the messages, and tell a trusted adult right away. It is not your fault. Be aware of your surroundings, travel with others when possible and trust your instincts. If you are in immediate danger, call 911. You may also tell a parent, teacher, school counselor, pastor or the school office at 954 851 6608.\n\nYour task: (1) List four signs of a healthy relationship and four signs of an unhealthy one. (2) Explain what to do if you are bullied or see bullying. (3) Write five rules for staying safe online.\n\nFlorida standards: HE.912.B.3, HE.912.P.7, PE.912.R.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "HE.912.B.3, HE.912.P.7, PE.912.R.5", "script": "Welcome back. Listen, the people around you shape who you become, so choose wisely.\n\nA healthy relationship has respect, honesty, trust, kindness, support and the freedom to say no. An unhealthy relationship may include control, jealousy, name calling, threats, pressure, cutting you off from other friends or violence. Abuse is never the fault of the person who is hurt.\n\nNow watch this. Peer pressure is the influence of friends and classmates. It can be good, like friends who encourage you to study and train. It can be harmful, like pressure to break rules or use substances. Proverbs 1:10 says, My son, if sinners entice thee, consent thou not. Know your values, choose friends who share them, and practice saying no calmly and firmly.\n\nLook at bullying. It is repeated, unwanted, hurtful behavior, including cyberbullying. If you are bullied, tell a trusted adult, save the evidence and do not retaliate. If you see it, do not join in, support the person and report it. Every person is made in God's image.\n\nStay safe online. Do not share passwords, your location or private photos. Never send or forward private pictures of anyone. If someone pressures or threatens you, stop, save the messages and tell a trusted adult right away. It is not your fault. If you are in danger, call 911. You can also tell a parent, teacher, counselor, pastor or the school office.\n\nYour task is to list signs of healthy and unhealthy relationships, explain what to do about bullying and write five online safety rules. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.4 Healthy Relationships and Safety$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 5, $j$Assessment 5: Health and Wellness$j$, $j${"prompt": "Write a report of at least 250 words on health and wellness. Use complete sentences and label each part. Philippians 4:6 says, Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God.\n\nPart 1: Explain how physical, mental, emotional, social and spiritual health are connected.\nPart 2: Describe stress and write a personal stress plan with at least three coping skills and one trusted person you would talk to.\nPart 3: Explain why sleep matters, and write a bedtime routine. Include one week of sleep tracking.\nPart 4: Explain three harms of tobacco, vaping, alcohol or drugs, and write a refusal script.\nPart 5: Describe a healthy relationship and a plan for staying safe online and responding to bullying.", "rubric": "100 points. Part 1: 15 points. Part 2: 20 points. Part 3: 20 points. Part 4: 20 points. Part 5: 20 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 5: Health and Wellness$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 5, $j$Discussion 5: Guarding the Heart and the Body$j$, $j${"prompt": "Write a post of at least 120 words that (1) tells one healthy way you handle stress, (2) explains why a teen might feel pressure to use substances and how to respond, (3) describes how you can be a good friend to someone who is struggling, and (4) connects your answer to Philippians 4:6 and 7 or First Peter 5:7. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why is asking for help a sign of strength? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 5: Guarding the Heart and the Body$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 21, $j$Check 5.1: Mental and Emotional Health$j$, $j${"questions": [{"q": "Stress is:", "options": ["Always harmful", "A sign of weakness", "The body's reaction to a demand", "A kind of food"]}, {"q": "Which is a healthy way to cope with stress?", "options": ["Lashing out at others", "Ignoring the problem", "Using drugs to escape", "Physical activity and talking with a trusted person"]}, {"q": "A person who feels hopeless for weeks should:", "options": ["Ask a trusted adult or professional for help", "Hide it", "Wait without telling anyone", "Stop eating"]}, {"q": "In a crisis, a person can call or text:", "options": ["No one", "311 only", "988", "411"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Mental and Emotional Health$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,0,2}'::int[], array[$j$Some stress is normal and can even help performance.$j$,$j$Healthy coping builds resilience.$j$,$j$Asking for help is a sign of strength.$j$,$j$The 988 Suicide and Crisis Lifeline is available at any time.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Mental and Emotional Health$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 22, $j$Check 5.2: Sleep and Rest$j$, $j${"questions": [{"q": "Teens need about how many hours of sleep each night?", "options": ["3 to 4", "8 to 10", "12 to 14", "5 to 6"]}, {"q": "Which is an effect of too little sleep?", "options": ["Stronger immunity", "Faster learning", "Poor focus and mood swings", "Better reaction time"]}, {"q": "Which habit helps sleep?", "options": ["Long afternoon naps", "Bright light at bedtime", "A regular schedule and screens off before bed", "Caffeine at night"]}, {"q": "Why are rest days important in training?", "options": ["They let the body recover and adapt", "They cause injury", "They are lazy", "They erase fitness"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: Sleep and Rest$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,2,0}'::int[], array[$j$The American Academy of Sleep Medicine recommends 8 to 10 hours for teens.$j$,$j$Lack of sleep hurts thinking, mood and health.$j$,$j$Consistent routines support good sleep.$j$,$j$Recovery is when the body gets stronger.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: Sleep and Rest$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 23, $j$Check 5.3: Avoiding Tobacco, Alcohol and Drugs$j$, $j${"questions": [{"q": "Nicotine is:", "options": ["A fruit", "A vitamin", "Harmless", "Highly addictive"]}, {"q": "Federal and Florida law set the minimum age to buy tobacco and vaping products at:", "options": ["12", "14", "21", "16"]}, {"q": "Counterfeit pills can be deadly because they may contain:", "options": ["Fentanyl", "Calcium", "Vitamin C", "Sugar only"]}, {"q": "A good refusal skill is to:", "options": ["Say no clearly and suggest something else", "Hide and say yes", "Take it to fit in", "Argue for an hour"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Avoiding Tobacco, Alcohol and Drugs$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,0,0}'::int[], array[$j$Nicotine is the addictive drug in tobacco and vaping products.$j$,$j$The minimum age is 21.$j$,$j$A tiny amount of fentanyl can kill.$j$,$j$Clear refusals and alternatives protect you.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Avoiding Tobacco, Alcohol and Drugs$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 24, $j$Check 5.4: Healthy Relationships and Safety$j$, $j${"questions": [{"q": "A sign of a healthy relationship is:", "options": ["Jealous control", "Respect and the freedom to say no", "Threats", "Isolation from friends"]}, {"q": "If you are bullied, you should:", "options": ["Keep it secret", "Hide it and retaliate", "Tell a trusted adult and save the evidence", "Bully back"]}, {"q": "Proverbs 1:10 teaches that when sinners entice you, you should:", "options": ["Join them", "Agree quietly", "Hide", "Not consent"]}, {"q": "If someone pressures you for private photos online, you should:", "options": ["Stop, save the messages and tell a trusted adult", "Reply with threats", "Delete everything and tell no one", "Send them"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Healthy Relationships and Safety$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,3,0}'::int[], array[$j$Healthy relationships are built on respect and trust.$j$,$j$Reporting helps stop bullying.$j$,$j$Wisdom refuses to follow harmful pressure.$j$,$j$It is not your fault, and trusted adults can help.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Healthy Relationships and Safety$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 25, $j$Unit Quiz 5: Health and Wellness$j$, $j${"questions": [{"q": "Mental and emotional health is about:", "options": ["Only sleep", "How we think, feel and cope", "Only grades", "Only muscle size"]}, {"q": "Which is an unhealthy way to cope with stress?", "options": ["Talking to a counselor", "Using drugs or alcohol to escape", "Exercise", "Prayer"]}, {"q": "Teens need about how many hours of sleep?", "options": ["12 to 14", "8 to 10", "4", "6"]}, {"q": "The teen brain continues developing until about:", "options": ["Age 13", "The mid twenties", "Age 15", "Age 10"]}, {"q": "Vaping aerosol is:", "options": ["A sports drink", "Pure water vapor", "Safe for lungs", "Not harmless and can contain nicotine and chemicals"]}, {"q": "Counterfeit pills can contain:", "options": ["Fentanyl", "Only water", "Only candy", "Only vitamins"]}, {"q": "An example of cyberbullying is:", "options": ["A phone call to a coach", "A group chat for homework", "Repeated hurtful messages online", "A friendly text"]}, {"q": "If you are in immediate danger, call:", "options": ["A friend only", "911", "No one", "A game hotline"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: Health and Wellness$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,1,1,3,0,2,1}'::int[], array[$j$It is part of whole person health.$j$,$j$Substances do not solve problems and can cause more.$j$,$j$Sleep supports growth, mood and learning.$j$,$j$That is why substances are especially risky for teens.$j$,$j$Vaping can harm the lungs and heart.$j$,$j$They can kill with a very small amount.$j$,$j$Cyberbullying uses digital tools to harm.$j$,$j$Emergency services can help right away.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: Health and Wellness$j$ on conflict (item_id) do nothing;
